// Atom inventories in µmol/L of reference cell volume, not molecular isotopologues.
const profile=(element,pair,fraction,title,names,atoms,edges,note)=>({element,pair,fraction,title,names,atoms,edges,note});
export const profiles={
 glucose:profile('C',[13,12],.0107,'U-¹³C₆ glucose',['Bath glucose','Cell glucose','Pyruvate','Lactate','CO₂ · collected'],[6,6,3,3,1],[[0,1,.025,'transport'],[1,0,.006,'transport'],[1,2,.02,'processing'],[2,3,.012,'processing'],[2,4,.008,'oxidation']],'Glucose → 2 pyruvate; carbon branches to lactate or a lumped complete-oxidation sink. No TCA intermediates or ATP yield are solved here.'),
 cholesterol:profile('C',[13,12],.0107,'U-¹³C₂₇ cholesterol',['Bath carrier','Internal free cholesterol','Membrane cholesterol','Stored cholesteryl ester'],[27,27,27,27],[[0,1,.008,'transport'],[1,0,.002,'transport'],[1,2,.012,'processing'],[2,1,.003,'processing'],[1,3,.006,'storage'],[3,1,.001,'storage']],'Tracks the 27 cholesterol carbons only, including the cholesterol moiety in esters; carrier delivery, ester fatty acids and membrane mechanics are not resolved.'),
 glutamine:profile('N',[15,14],.00364,'¹⁵N₂ glutamine',['Bath glutamine','Cell glutamine','Transferred nitrogen','Protein nitrogen'],[2,2,1,1],[[0,1,.025,'transport'],[1,0,.006,'transport'],[1,2,.012,'processing'],[2,3,.006,'storage'],[3,2,.001,'storage']],'Both glutamine nitrogens enter a lumped N pool. Amide/amine positions and individual amino-acid or protein stoichiometries are not resolved.'),
 sulfur:profile('S',[34,32],.0425/(.9499+.0425),'³⁴S methionine',['Bath methionine','Cell methionine','Transferred sulfur','Protein sulfur'],[1,1,1,1],[[0,1,.015,'transport'],[1,0,.004,'transport'],[1,2,.008,'processing'],[2,3,.004,'storage'],[3,2,.001,'storage']],'A sulfur-atom ledger with lumped transfer and incorporation; not a methionine-cycle or glutathione model.'),
 copper:profile('Cu',[65,63],.3085,'⁶⁵Cu / ⁶³Cu',['Bath carrier','Mobile copper','Protein-bound copper','Organelle copper'],[1,1,1,1],[[0,1,.008,'transport'],[1,0,.004,'transport'],[1,2,.02,'processing'],[2,1,.002,'processing'],[1,3,.006,'storage'],[3,1,.001,'storage']],'Generic ligand-associated copper pools. No free-ion concentrations, Cu(I)/Cu(II), toxicity or specific metalloproteins are solved.'),
 zinc:profile('Zn',[68,64],.1845/(.4917+.1845),'⁶⁸Zn / ⁶⁴Zn',['Bath carrier','Mobile zinc','Protein-bound zinc','Stored zinc'],[1,1,1,1],[[0,1,.012,'transport'],[1,0,.005,'transport'],[1,2,.025,'processing'],[2,1,.003,'processing'],[1,3,.006,'storage'],[3,1,.001,'storage']],'Generic zinc transport and buffering; not measured free Zn²⁺ or a transporter-specific model.'),
 calcium:profile('Ca',[44,40],.02086/(.96941+.02086),'⁴⁴Ca / ⁴⁰Ca',['Bath calcium','Mobile calcium','Bound calcium','Stored calcium'],[1,1,1,1],[[0,1,.008,'transport'],[1,0,.03,'transport'],[1,2,.02,'processing'],[2,1,.008,'processing'],[1,3,.02,'storage'],[3,1,.002,'storage']],'Atom exchange only. This is not free cytosolic Ca²⁺, an ER release model or calcium signalling; there is no electrical feedback.'),
 iron:profile('Fe',[57,56],.02119/(.91754+.02119),'⁵⁷Fe / ⁵⁶Fe',['Bath carrier','Mobile iron','Protein-bound iron','Stored iron'],[1,1,1,1],[[0,1,.006,'transport'],[1,0,.001,'transport'],[1,2,.012,'processing'],[2,1,.001,'processing'],[1,3,.009,'storage'],[3,1,.0005,'storage']],'Generic iron pools, not explicit transferrin, ferritin, heme or iron–sulfur cluster assembly.'),
 magnesium:profile('Mg',[25,24],.1/(.7899+.1),'²⁵Mg / ²⁴Mg',['Bath magnesium','Mobile magnesium','Ligand-bound magnesium','Organelle magnesium'],[1,1,1,1],[[0,1,.015,'transport'],[1,0,.008,'transport'],[1,2,.025,'processing'],[2,1,.01,'processing'],[1,3,.006,'storage'],[3,1,.003,'storage']],'Generic Mg binding and exchange; MgATP speciation and its effects on enzymes are not solved.'),
 selenium:profile('Se',[80,78],.4961/(.4961+.2377),'⁸⁰Se / ⁷⁸Se',['Bath selenium carrier','Mobile selenium','Processed selenium','Protein selenium'],[1,1,1,1],[[0,1,.008,'transport'],[1,0,.002,'transport'],[1,2,.006,'processing'],[2,3,.003,'storage'],[3,2,.0005,'storage']],'Carrier-unspecified selenium atom pools, not a selenite-reduction or selenoprotein-synthesis reaction network.')
};
export const referenceRates={transport:1,processing:1,storage:1};
export function createRun(id){const p=profiles[id],amounts=p.names.map((_,i)=>i===0?100:i===1?20:10);return {id,time:0,active:false,heavy:amounts.map(x=>x*p.fraction),light:amounts.map(x=>x*(1-p.fraction)),initial:amounts.reduce((a,b)=>a+b,0),inH:0,inL:0,outH:0,outL:0,rates:{...referenceRates},history:[],events:[]};}
export function replaceBath(s,fraction){const amount=s.heavy[0]+s.light[0];s.outH+=s.heavy[0];s.outL+=s.light[0];s.heavy[0]=amount*fraction;s.light[0]=amount*(1-fraction);s.inH+=s.heavy[0];s.inL+=s.light[0];s.active=true;s.events.push({time:s.time,fraction});}
export function stepRun(s,dt,oxygen=.2){if(!s.active)return;const p=profiles[s.id];for(const [from,to,k,type] of p.edges){const factor=type==='oxidation'?s.rates.processing*(oxygen/(.01+oxygen))/(.2/.21):s.rates[type];const fraction=-Math.expm1(-k*factor*dt);for(const amounts of [s.heavy,s.light]){const moved=amounts[from]*fraction;amounts[from]-=moved;amounts[to]+=moved;}}s.time+=dt;}
export function poolStats(s,i,volume=1){const h=s.heavy[i],l=s.light[i],sum=h+l;return {total:sum/volume,heavy:h/volume,light:l/volume,fraction:sum?h/sum:0,ratio:l?h/l:null,molecules:sum/volume/profiles[s.id].atoms[i]};}
export function balanceError(s){const f=profiles[s.id].fraction;return Math.max(Math.abs(s.heavy.reduce((a,b)=>a+b,0)+s.outH-s.inH-s.initial*f),Math.abs(s.light.reduce((a,b)=>a+b,0)+s.outL-s.inL-s.initial*(1-f)));}
